import json
LEN={'A':946.5,'B':694.4,'C':779.9,'D':783.2,'E':1044.3,'F':652.1,'G':809.7,'H':608.4,'I':1149.6,'J':837.4,'K':770.4,'L':676.5,'M':1020.7,'N':603.0,'O':687.5,'P':928.9,'Q':748.8,'R':709.2,'S':649.8,'T':816.2,'U':914.6,'V':766.0}
s=json.load(open('output/solution.json'))['sequence']
errs=[]
for e in s:
    v=e['video']; i=e['id']; ts=e['t_start']; te=e['t_end']
    if not (1<=i<=84): errs.append(('badid',e))
    if not (ts<te): errs.append(('order',e))
    if ts<0 or te>LEN[v]+1: errs.append(('range',e))
# check per-video sorted by t_start
from itertools import groupby
for v,g in groupby(s,key=lambda x:x['video']):
    g=list(g); starts=[x['t_start'] for x in g]
    if starts!=sorted(starts): errs.append(('unsorted',v))
# per-video counts
from collections import Counter
c=Counter(e['video'] for e in s)
print('per-video entry counts:')
for v in sorted(c): print(' ',v,c[v])
print('ERRORS:',errs if errs else 'none')
print('keys ok:', all(set(e.keys())=={'video','id','t_start','t_end'} for e in s))
